    if issecretvalue and issecretvalue(value) then return false end
    return true
end--[[APR_DIAG]]; accessible = APRTrace("APR-Core/utils/DungeonUtils.lua:10:accessible#1", accessible)--[[/APR_DIAG]]

local function accessibleTable(value)
